const input = $input.first().json;
const execution = input.execution ?? {};
const trigger = input.trigger ?? {};
const error = execution.error ?? trigger.error ?? {};
let message = String(error.message ?? 'Unknown workflow error');
// Avoid exporting secrets, contact data, or the raw request in the alert.
for (const secret of [$env.N8N_WEBHOOK_SECRET,$env.CONVEX_INBOUND_SECRET,$env.N8N_ENCRYPTION_KEY]) {
  if (secret) message = message.split(secret).join('[redacted]');
}
message = message.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[email redacted]').slice(0, 500);
let executionUrl = String(execution.url ?? 'unavailable');
executionUrl = executionUrl.split('?')[0].split('#')[0];
return [{json:{workflow:String(input.workflow?.name ?? input.workflow?.id ?? 'unknown'),node:String(execution.lastNodeExecuted ?? error.node?.name ?? 'trigger'),executionUrl,message}}];

const alert = $input.first().json;
console.error(JSON.stringify({level:'error',source:'lendloop-automation',...alert}));
// MOCK ALERT ONLY. Replace with your monitoring provider after configuration.
return [{json:{...alert,alertChannel:'mock-log'}}];
